use kimo_core::{commands::{Session,dispatch},masks,model::Mask};use serde_json::json;
fn scene()->(Session,String,String){let mut s=Session::new();dispatch(&mut s,"project_set",&json!({"width":64,"height":48,"fps":25})).unwrap();let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();let mut ids=vec![];for col in [[0.3,0.2,0.1],[0.6,0.4,0.2]]{let c=dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"solid","color":col,"start":0,"duration":1})).unwrap()["clip_id"].as_str().unwrap().to_string();let l=masks::new_layer("bg".into(),"alpha");s.project.find_clip_mut(&c).unwrap().mask=Some(Mask{shape:"stack".into(),props:Default::default(),layers:vec![l],matte:None,invert:false});ids.push(c);} (s,ids[0].clone(),ids[1].clone())}
fn args(a:&str,b:&str)->serde_json::Value{static NEXT:std::sync::atomic::AtomicUsize=std::sync::atomic::AtomicUsize::new(0);let n=NEXT.fetch_add(1,std::sync::atomic::Ordering::Relaxed);json!({"clip_id":a,"ref_clip_id":b,"time":0.4,"ref_time":0.4,"source_regions":{"background":"bg"},"ref_regions":{"background":"bg"},"before_path":format!("/tmp/subject-before-{}-{n}.png",std::process::id()),"after_path":format!("/tmp/subject-after-{}-{n}.png",std::process::id())})}
#[test]fn preview_nonmutating_and_stats(){let(mut s,a,b)=scene();let before=serde_json::to_value(&s.project).unwrap();let r=dispatch(&mut s,"preview_subject_match",&args(&a,&b)).unwrap();assert_eq!(serde_json::to_value(&s.project).unwrap(),before);assert_eq!(r["mutated"],false);assert_eq!(r["source_stats"][0],serde_json::Value::Null);let src=r["source_stats"][1]["log_luminance_mean"].as_f64().unwrap();let target=r["reference_stats"][1]["log_luminance_mean"].as_f64().unwrap();let after=r["result_stats"][1]["log_luminance_mean"].as_f64().unwrap();assert!((after-target).abs()<(src-target).abs()*0.01);}
#[test]fn rejects_missing_overlap_geometry_unknown(){let(mut s,a,b)=scene();let mut q=args(&a,&b);q["source_regions"]["background"]=json!("missing");assert!(dispatch(&mut s,"preview_subject_match",&q).is_err());let mut q=args(&a,&b);q["source_regions"]["skin"]=json!("bg");q["ref_regions"]["skin"]=json!("bg");assert!(dispatch(&mut s,"preview_subject_match",&q).is_err());let mut q=args(&a,&b);q["options"]=json!({"amout":0});assert!(dispatch(&mut s,"preview_subject_match",&q).is_err());s.project.find_clip_mut(&a).unwrap().props.insert("rot_x".into(),kimo_core::keyframe::Prop::new(5.));assert!(dispatch(&mut s,"preview_subject_match",&args(&a,&b)).is_err());}
#[test]fn amountzero_png_exact_and_managed_domain(){let(mut s,a,b)=scene();let mut q=args(&a,&b);q["options"]=json!({"amount":0});let r=dispatch(&mut s,"preview_subject_match",&q).unwrap();assert_eq!(std::fs::read(r["before_path"].as_str().unwrap()).unwrap(),std::fs::read(r["after_path"].as_str().unwrap()).unwrap());dispatch(&mut s,"set_color_pipeline",&json!({"settings":{"enabled":true,"working_gamut":3}})).unwrap();assert!(dispatch(&mut s,"preview_subject_match",&q).is_ok());}
#[test]fn soft_semantic_masks_do_not_crop_preview(){let(mut s,a,b)=scene();for id in [&a,&b]{let c=s.project.find_clip_mut(id).unwrap();let mut l=masks::new_layer("bg".into(),"rect");for(k,v)in[("cx",0.5),("cy",0.2),("w",0.6),("h",0.3),("feather",20.)]{l.props.insert(k.into(),kimo_core::keyframe::Prop::new(v));}c.mask.as_mut().unwrap().layers=vec![l];}let q=args(&a,&b);let r=dispatch(&mut s,"preview_subject_match",&q).unwrap();let decode=|path:&str|std::process::Command::new("ffmpeg").args(["-v","error","-i",path,"-f","rawvideo","-pix_fmt","rgba","-"]).output().unwrap().stdout;let before=decode(r["before_path"].as_str().unwrap());let after=decode(r["after_path"].as_str().unwrap());for i in 0..64*48{assert_eq!(before[i*4+3],255);assert_eq!(after[i*4+3],255);}assert_eq!(&before[(47*64)*4..],&after[(47*64)*4..]);}
